import {HelpView} from '../../src/features/help.ts';import {CreditsView} from '../../src/features/credits.ts';import {parseCredits} from '../../src/domain/credits.ts';import builtin from '../../src/data/credits.json';
export function createHelpCreditsFixture(){let data:unknown=builtin,pending=false,fail=false,resolve:((r:any)=>void)|undefined;const host=()=>document.querySelector<HTMLElement>('#help-credits-host')!,help=new HelpView(),credits=new CreditsView(async()=>{if(fail)throw Error('read failed');if(pending)return new Promise(r=>resolve=r);return {credits:parseCredits(data),warning:''};});return {help:(group='school')=>{credits.leave();help.mount(host(),group);},credits:()=>{help.leave();credits.mount(host());},data:(v:unknown)=>data=v,pending:(v:boolean)=>pending=v,fail:(v:boolean)=>fail=v,resolve:()=>resolve?.({credits:parseCredits({items:[{name:'迟到名单',contribution:'旧页面'}]}),warning:''})};}
